pid_t tgid = target_process_id;
pid_t tid = target_thread_id;
int sig = SIGRTMIN + 1;

siginfo_t info = {0};
info.si_code = SI_QUEUE;
info.si_errno = 0;
info.si_value.sival_int = 0xDEADBEEF;

/*
 * Sends data ('info') associated with 'sig'
 * specifically to 'tid' within thread group 'tgid'.
 */
long result = syscall(SYS_rt_tgsigqueueinfo,
                      tgid, tid,
                      sig, &info);
